import{_ as l,a0 as n,w as p,s as d,ao as r,I as a,x as e,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"用開源搜索引擎定製你的互聯網 | LCTT x X-CMD","titleTemplate":false,"description":"用開源搜索引擎定製你的互聯網 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用開源搜索引擎定製你的互聯網 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用開源搜索引擎定製你的互聯網 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200207 Customize your internet with an open source search engine","title":"用開源搜索引擎定製你的互聯網","tag":"202002","desc":""},"relativePath":"202002/20200207 Customize your internet with an open source search engine.md","filePath":"[post].md"}'),u={name:"202002/20200207 Customize your internet with an open source search engine.md"};function f(y,t,m,C,g,x){const o=n("Link");return p(),d("div",null,[t[32]||(t[32]=r('<h1 id="用開源搜索引擎定製你的互聯網" tabindex="-1">用開源搜索引擎定製你的互聯網 <a class="header-anchor" href="#用開源搜索引擎定製你的互聯網" aria-label="Permalink to “用開源搜索引擎定製你的互聯網”">​</a></h1><blockquote><p>上手開源的對等 Web 索引器 YaCy。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/19/103541la7erglz7oloa4ye.jpg" alt=""></p><p>很久以前，互聯網很小，小到幾個人就可以索引它們，這些人收集了所有網站的名稱和鏈接，並按主題將它們分別列在頁面或印刷書籍中。隨着萬維網網絡的發展，形成了“網站環”形式，具有類似的內容、主題或敏感性的站點捆綁在一起，形成了通往每個成員的循環路徑。環中任何站點的訪問者都可以單擊按鈕以轉到環中的下一個或上一個站點，以發現與其興趣相關的新站點。</p><p>又過了一段時間，互聯網似乎變得臃腫不堪了。每個人都在網絡上，有很多冗餘信息和垃圾郵件，多到讓你無法找到任何東西。Yahoo 和 AOL、CompuServe 以及類似的服務各自採用了不同的方法來解決這個問題，但是直到谷歌出現後，現代的搜索模型才得以普及。按谷歌的做法，互聯網應該通過搜索引擎進行索引、排序和排名。</p><h3 id="為什麼選擇開源替代品" tabindex="-1">為什麼選擇開源替代品？ <a class="header-anchor" href="#為什麼選擇開源替代品" aria-label="Permalink to “為什麼選擇開源替代品？”">​</a></h3><p>像谷歌和 DuckDuckGo 這樣的搜索引擎顯然是卓有成效的。你可能是通過搜索引擎訪問的本站。儘管對於因主機沒有選擇遵循優化搜索引擎的最佳實踐從而導致會內容陷入困境這件事仍存在爭論，但用於管理豐富的文化、知識和輕率的信息（即互聯網）的現代解決方案是冷冰冰的索引。</p>',7)),a("p",null,[t[1]||(t[1]=e("但是也許出於隱私方面的考慮，或者你希望為使互聯網更加獨立而做出貢獻，你或許不願意使用谷歌或 DuckDuckGo。如果你對此感興趣，那麼可以考慮參加 ",-1)),s(o,{href:"https://yacy.net/"},{default:i(()=>[...t[0]||(t[0]=[e("YaCy",-1)])]),_:1}),t[2]||(t[2]=e("，這是一個對等互聯網索引器和搜索引擎。",-1))]),t[33]||(t[33]=a("h3",{id:"安裝-yacy",tabindex:"-1"},[e("安裝 YaCy "),a("a",{class:"header-anchor",href:"#安裝-yacy","aria-label":"Permalink to “安裝 YaCy”"},"​")],-1)),a("p",null,[t[5]||(t[5]=e("要安裝並嘗試 YaCy，請首先確保已安裝 Java。如果你使用的是 Linux，則可以按照我的《",-1)),s(o,{href:"https://linux.cn/article-11614-1.html"},{default:i(()=>[...t[3]||(t[3]=[e("如何在 Linux 上安裝 Java",-1)])]),_:1}),t[6]||(t[6]=e("》中的説明進行操作。如果你使用 Windows 或 MacOS，請從 ",-1)),s(o,{href:"https://adoptopenjdk.net/releases.html"},{default:i(()=>[...t[4]||(t[4]=[e("AdoptOpenJDK.net",-1)])]),_:1}),t[7]||(t[7]=e(" 獲取安裝程序。",-1))]),a("p",null,[t[9]||(t[9]=e("安裝 Java 後，請根據你的平台",-1)),s(o,{href:"https://yacy.net/download_installation/"},{default:i(()=>[...t[8]||(t[8]=[e("下載安裝程序",-1)])]),_:1}),t[10]||(t[10]=e("。",-1))]),t[34]||(t[34]=r('<p>如果你使用的是 Linux，請解壓縮 tarball 並將其移至 <code>/opt</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar --extract --file  yacy_*z --directory /opt</span></span></code></pre></div><p>根據下載的安裝程序的説明啓動 YaCy。</p><p>在 Linux 上，啓動在後台運行的 YaCy：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /opt/startYACY.sh &amp;</span></span></code></pre></div><p>在 Web 瀏覽器中，導航到 <code>localhost:8090</code> 並進行搜索。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-startpage.jpg" alt="YaCy start page" title="YaCy start page"></p><h3 id="將-yacy-添加到你的地址欄" tabindex="-1">將 YaCy 添加到你的地址欄 <a class="header-anchor" href="#將-yacy-添加到你的地址欄" aria-label="Permalink to “將 YaCy 添加到你的地址欄”">​</a></h3><p>如果你使用的是 Firefox Web 瀏覽器，則只需單擊幾下，即可在 Awesome Bar（Mozilla 給 URL 欄起的名稱）中將 YaCy 設置為默認搜索引擎。</p><p>首先，如果尚未顯示，在 Firefox 工具欄中使專用搜索欄顯示出來（你不必使搜索欄保持一直可見；只需要激活它足夠長的時間即可添加自定義搜索引擎）。Firefox 右上角的“漢堡”菜單中的“自定義”菜單中提供了搜索欄。在 Firefox 工具欄上的搜索欄可見後，導航至 <code>localhost:8090</code>，然後單擊剛添加的 Firefox 搜索欄中的放大鏡圖標。單擊選項將 YaCy 添加到你的 Firefox 的搜索引擎中。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-add-firefox.jpg" alt="Adding YaCy to Firefox" title="Adding YaCy to Firefox"></p><p>完成此操作後，你可以在 Firefox 首選項中將其標記為默認值，或者僅在 Firefox 搜索欄中執行的搜索中選擇性地使用它。如果將其設置為默認搜索引擎，則可能不需要專用搜索欄，因為 Awesome Bar 也使用默認引擎，因此可以將其從工具欄中刪除。</p><h3 id="對等搜索引擎如何工作" tabindex="-1">對等搜索引擎如何工作 <a class="header-anchor" href="#對等搜索引擎如何工作" aria-label="Permalink to “對等搜索引擎如何工作”">​</a></h3>',13)),a("p",null,[t[12]||(t[12]=e("YaCy 是一個開源的分佈式搜索引擎。它是用 ",-1)),s(o,{href:"https://opensource.com/resources/java"},{default:i(()=>[...t[11]||(t[11]=[e("Java",-1)])]),_:1}),t[13]||(t[13]=e(" 編寫的，因此可以在任何平台上運行，並且可以執行 Web 爬網、索引和搜索。這是一個對等（P2P）網絡，因此每個運行 YaCy 的用户都將努力地不斷跟蹤互聯網的變化情況。當然，沒有單個用户能擁有整個互聯網的完整索引，因為這將需要一個數據中心來容納，但是該索引分佈在所有 YaCy 用户中且是冗餘的。它與 BitTorrent 非常相似（因為它使用分佈式哈希表 DHT 來引用索引條目），只不過你所共享的數據是單詞和 URL 關聯的矩陣。通過混合哈希表返回的結果，沒人能説出誰搜索了哪些單詞，因此所有搜索在功能上都是匿名的。這是用於無偏見、無廣告、未跟蹤和匿名搜索的有效系統，你只需要使用它就加入了它。",-1))]),t[35]||(t[35]=a("h3",{id:"搜索引擎和算法",tabindex:"-1"},[e("搜索引擎和算法 "),a("a",{class:"header-anchor",href:"#搜索引擎和算法","aria-label":"Permalink to “搜索引擎和算法”"},"​")],-1)),t[36]||(t[36]=a("p",null,"索引互聯網的行為是指將網頁分成單個單詞，然後將頁面的 URL 與每個單詞相關聯。在搜索引擎中搜索一個或多個單詞將獲取與該查詢關聯的所有 URL。YaCy 客户端在運行時也是如此。",-1)),t[37]||(t[37]=a("p",null,[e("客户端要做的另一件事是為你的瀏覽器提供搜索界面。你可以將 Web 瀏覽器指向 "),a("code",null,"localhost:8090"),e(" 來搜索 YaCy，而不是在要搜索時導航到谷歌。你甚至可以將其添加到瀏覽器的搜索欄中（取決於瀏覽器的可擴展性），因此可以從 URL 欄中進行搜索。")],-1)),t[38]||(t[38]=a("h3",{id:"yacy-的防火牆設置",tabindex:"-1"},[e("YaCy 的防火牆設置 "),a("a",{class:"header-anchor",href:"#yacy-的防火牆設置","aria-label":"Permalink to “YaCy 的防火牆設置”"},"​")],-1)),t[39]||(t[39]=a("p",null,"首次開始使用 YaCy 時，它可能運行在“初級”模式下。這意味着你的客户端爬網的站點僅對你可用，因為其他 YaCy 客户端無法訪問你的索引條目。要加入對等環境，必須在路由器的防火牆（或者你正在運行的軟件防火牆）中打開端口 8090，這稱為“高級”模式。",-1)),a("p",null,[t[15]||(t[15]=e("如果你使用的是 Linux，則可以在《",-1)),s(o,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:i(()=>[...t[14]||(t[14]=[e("使用防火牆讓你的 Linux 更加強大",-1)])]),_:1}),t[16]||(t[16]=e("》中找到有關計算機防火牆的更多信息。在其他平台上，請參考操作系統的文檔。",-1))]),t[40]||(t[40]=r('<p>互聯網服務提供商（ISP）提供的路由器上幾乎總是啓用了防火牆，並且有太多種類的防火牆無法準確説明。大多數路由器都提供了在防火牆上“打洞”的選項，因為許多流行的聯網遊戲都需要雙向流量。</p><p>如果你知道如何登錄路由器（通常為 192.168.0.1 或 10.1.0.1，但可能因製造商的設置而異），則登錄並查找配置面板來控制“防火牆”或“端口轉發”或“應用”。</p><p>找到路由器防火牆的首選項後，將端口 8090 添加到白名單。例如：</p><p><img src="https://opensource.com/sites/default/files/uploads/router-add-app.jpg" alt="Adding YaCy to an ISP router" title="Adding YaCy to an ISP router"></p><p>如果路由器正在進行端口轉發，則必須使用相同的端口將傳入的流量轉發到計算機的 IP 地址。例如：</p><p><img src="https://opensource.com/sites/default/files/uploads/router-add-app1.jpg" alt="Adding YaCy to an ISP router" title="Adding YaCy to an ISP router"></p><p>如果由於某種原因無法調整防火牆設置，那也沒事。YaCy 將繼續以初級模式運行並作為對等搜索網絡的客户端運行。</p><h3 id="你的互聯網" tabindex="-1">你的互聯網 <a class="header-anchor" href="#你的互聯網" aria-label="Permalink to “你的互聯網”">​</a></h3><p>使用 YaCy 搜索引擎可以做的不僅僅是被動搜索。你可以強制抓取不太顯眼的網站，可以請求對網站進行網絡抓取，可以選擇使用 YaCy 進行本地搜索等等。你可以更好地控制<em>你的</em>互聯網的所呈現的一切。高級用户越多，索引的網站就越多。索引的網站越多，所有用户的體驗就越好。加入吧！</p><hr>',10)),a("p",null,[t[18]||(t[18]=e("via: ",-1)),s(o,{href:"https://opensource.com/article/20/2/open-source-search-engine"},{default:i(()=>[...t[17]||(t[17]=[e("https://opensource.com/article/20/2/open-source-search-engine",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=e("作者：",-1)),s(o,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[19]||(t[19]=[e("Seth Kenlon",-1)])]),_:1}),t[24]||(t[24]=e(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[20]||(t[20]=[e("lujun9972",-1)])]),_:1}),t[25]||(t[25]=e(" 譯者：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[21]||(t[21]=[e("wxy",-1)])]),_:1}),t[26]||(t[26]=e(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[22]||(t[22]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[29]||(t[29]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[27]||(t[27]=[e("LCTT",-1)])]),_:1}),t[30]||(t[30]=e(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:i(()=>[...t[28]||(t[28]=[e("Linux中國",-1)])]),_:1}),t[31]||(t[31]=e(" 榮譽推出",-1))])])}const T=l(u,[["render",f]]);export{k as __pageData,T as default};
